#' RD Difference-in-Discontinuities
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param period .
#' @param unit .
#' @param cutoff .
#' @param p .
#' @param bwselect .
#' @param kernel .
#' @param vce .
#' @param level .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
rddid <- function(
    data,
    outcome,
    running,
    period,
    unit,
    cutoff = 0,
    p = 1,
    bwselect = "mserd",
    kernel = "triangular",
    vce = "nn",
    level = 95,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rddid requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(period)) period <- jmvcore::resolveQuo(jmvcore::enquo(period))
    if ( ! missing(unit)) unit <- jmvcore::resolveQuo(jmvcore::enquo(unit))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(period), period, NULL),
            `if`( ! missing(unit), unit, NULL))


    options <- rddidOptions$new(
        outcome = outcome,
        running = running,
        period = period,
        unit = unit,
        cutoff = cutoff,
        p = p,
        bwselect = bwselect,
        kernel = kernel,
        vce = vce,
        level = level,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rddidClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

